using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.Fiscal;
public class FiscalService{readonly ErpDbContext _db;readonly IFiscalProvider _provider;public FiscalService(ErpDbContext db,IFiscalProvider provider){_db=db;_provider=provider;}
 public async Task<NotaFiscal> PrepararAsync(int vendaId,string modelo){var v=await _db.Vendas.Include(x=>x.Itens).SingleAsync(x=>x.Id==vendaId);var cfg=await _db.ConfiguracoesFiscais.FirstOrDefaultAsync()??throw new InvalidOperationException("Configure os dados fiscais da empresa.");if(string.IsNullOrWhiteSpace(cfg.Cnpj)||string.IsNullOrWhiteSpace(cfg.Uf))throw new InvalidOperationException("CNPJ e UF são obrigatórios.");var numero=modelo=="65"?cfg.ProximoNumeroNFCe++:cfg.ProximoNumeroNFe++;var serie=modelo=="65"?cfg.SerieNFCe:cfg.SerieNFe;var n=new NotaFiscal{VendaId=v.Id,Modelo=modelo,Numero=numero,Serie=serie,Ambiente=cfg.Ambiente,ValorTotal=v.Total,Status="PRONTA_PARA_ENVIO"};_db.NotasFiscais.Add(n);v.StatusFiscal=modelo=="65"?"NFCE_PREPARADA":"NFE_PREPARADA";await _db.SaveChangesAsync();return n;}
 public async Task<FiscalResult> EmitirAsync(int notaId){var n=await _db.NotasFiscais.Include(x=>x.Venda).SingleAsync(x=>x.Id==notaId);var cfg=await _db.ConfiguracoesFiscais.SingleAsync();var r=await _provider.EmitirAsync(n,cfg);n.Status=r.Status;n.ChaveAcesso=r.Chave;n.Protocolo=r.Protocolo;n.XmlRetorno=r.Xml;n.MotivoRejeicao=r.Sucesso?"":r.Mensagem;if(r.Sucesso){n.DataAutorizacao=DateTime.Now;if(n.Venda!=null)n.Venda.StatusFiscal="AUTORIZADA";}await _db.SaveChangesAsync();return r;}}